import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

log_softmax_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void log_softmax_kernel(const float* __restrict__ x,
                                   float* __restrict__ y,
                                   int batch_size,
                                   int dim) {
    int row = blockIdx.x;
    if (row < batch_size) {
        // 1. Find max value for numerical stability
        float max_val = -INFINITY;
        for (int i = 0; i < dim; i++) {
            float val = x[row * dim + i];
            if (val > max_val) {
                max_val = val;
            }
        }
        // 2. Compute sum of exponentials
        float sum_val = 0.0f;
        for (int i = 0; i < dim; i++) {
            sum_val += expf(x[row * dim + i] - max_val);
        }
        float log_sum = max_val + logf(sum_val);
        // 3. Subtract log_sum from each element
        for (int i = 0; i < dim; i++) {
            y[row * dim + i] = x[row * dim + i] - log_sum;
        }
    }
}

torch::Tensor log_softmax_cuda(torch::Tensor x) {
    auto output = torch::zeros_like(x);
    int batch_size = x.size(0);
    int dim = x.size(1);

    const int blocks = batch_size;
    const int threads = 1;  // Each block processes one row

    log_softmax_kernel<<<blocks, threads>>>(x.data_ptr<float>(),
                                           output.data_ptr<float>(),
                                           batch_size,
                                           dim);
    return output;
}
"""

log_softmax_cpp_source = "torch::Tensor log_softmax_cuda(torch::Tensor x);"

# Build the custom log_softmax extension
log_softmax_kernel = load_inline(
    name="log_softmax_kernel",
    cpp_sources=log_softmax_cpp_source,
    cuda_sources=log_softmax_source,
    functions=["log_softmax_cuda"],
    verbose=False,
    extra_cflags=[],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    """
    Optimized model that performs a custom LogSoftmax activation via a custom CUDA kernel.
    """
    def __init__(self, dim: int = 1):
        super(ModelNew, self).__init__()
        self.dim = dim
        self.log_softmax_kernel = log_softmax_kernel

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # For simplicity, we assume dim=1 as in the original code
        # and that x is 2D (batch_size, dim).
        return self.log_softmax_kernel.log_softmax_cuda(x)

